package com.opentv.app.ui;
import android.view.*;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.opentv.app.R;import com.opentv.app.data.FavoritesStore;import com.opentv.app.model.Channel;import com.opentv.app.util.LogoLoader;import java.util.*;
public class ChannelAdapter extends RecyclerView.Adapter<ChannelAdapter.Holder>{public interface Listener{void onPlay(Channel c);void onFavoriteChanged(Channel c,boolean n);}private final List<Channel>items=new ArrayList<>();private final Listener listener;private final FavoritesStore fav;public ChannelAdapter(FavoritesStore f,Listener l){fav=f;listener=l;setHasStableIds(true);}public void setItems(List<Channel>v){items.clear();items.addAll(v);notifyDataSetChanged();}public long getItemId(int p){return items.get(p).url.hashCode();}
@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_channel,p,false));}public void onBindViewHolder(@NonNull Holder h,int p){Channel c=items.get(p);h.name.setText(c.name);h.meta.setText(c.subtitle());h.star.setVisibility(fav.contains(c.url)?View.VISIBLE:View.GONE);LogoLoader.load(h.logo,c.logo);h.card.setOnClickListener(v->listener.onPlay(c));h.card.setOnLongClickListener(v->{boolean n=fav.toggle(c);h.star.setVisibility(n?View.VISIBLE:View.GONE);listener.onFavoriteChanged(c,n);return true;});}public int getItemCount(){return items.size();}
static class Holder extends RecyclerView.ViewHolder{final View card;final ImageView logo;final TextView name,meta,star;Holder(View v){super(v);card=v.findViewById(R.id.channelCard);logo=v.findViewById(R.id.channelLogo);name=v.findViewById(R.id.channelName);meta=v.findViewById(R.id.channelMeta);star=v.findViewById(R.id.favoriteBadge);}}}
